import numpy as np
from scipy.special import erf
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
C9=F['C9'].astype(np.float64); M9=F['M9'].astype(np.float64)
def gelu(z): return 0.5*z*(1+erf(z/np.sqrt(2)))
def ridge_W(Xtr,Y,lam):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0); n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return Wt, ym-xm@Wt
k2=384; k1=384
ec,Vc=np.linalg.eigh(np.cov(C9.T)); Q=Vc[:,:k2]
mM=M9.mean(0); sM=M9.std(0); Ms=(M9-mM)/sM
_,_,VtM=np.linalg.svd(Ms,full_matrices=False); PM=VtM[:k2].T
sc=Ms@PM
mC=C9.mean(0); sC=C9.std(0)
lam=0.3
u=C9+lam*sc@Q.T; mu_u=u.mean(1,keepdims=True); sig=np.sqrt(((u-mu_u)**2).mean(1,keepdims=True))
x=(u-mu_u)/sig
print('sigma_u pct',np.percentile(sig,[1,50,99]))
sb=sig.mean()
Pn=np.eye(768)-Q@Q.T
LC=(x@Pn)*sb/sC            # ~ C9 (nonQ part) / sC
LM=(x@Q)*sb/lam            # ~ sc
LCc=LC-LC.mean(0); 
_,_,VtC=np.linalg.svd(LCc,full_matrices=False); RC=LCc@VtC[:k1].T
np.savez('sim_x.npz',LC=LC,LM=LM,RC=RC)
def cv(lams,wl,b,t,wm=1.0,kern=True,wlm=1.0):
    Lin=np.concatenate([LCc,wlm*(LM-LM.mean(0))],1)
    R=np.concatenate([RC,wm*(LM-LM.mean(0))],1); rbar=np.linalg.norm(R,axis=1).mean()
    res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f; Y=np.eye(8)[y[tr]]-1/8
            if kern:
                Rn=R[tr]/np.linalg.norm(R[tr],axis=1,keepdims=True)
                Z=np.concatenate([wl*Lin,gelu(b*(R@Rn.T)/rbar-t)],1)
            else: Z=Lin
            for l in lams:
                Wt,bb=ridge_W(Z[tr],Y,l); res[l]+=((Z[te]@Wt+bb).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
print('lin', cv([100,300,1000],1,0,0,kern=False))
for b,t in [(10,4.5),(10,5.5),(15,8)]:
